import hashlib
import logging
import math
import os
import re
from typing import List, Optional, Tuple

logger = logging.getLogger(__name__)


class EmbeddingError(RuntimeError):
    """Raised when embedding generation fails and fallback is disallowed."""
    pass


class IncompatibleEmbeddingModelError(ValueError):
    """Raised when comparing vectors generated by different embedding models."""
    pass


class EmbeddingService:
    """Embedding service generating vector embeddings using Google GenAI or local fallback."""

    MODEL_GEMINI = os.getenv("GEMINI_EMBEDDING_MODEL", "gemini-embedding-001")
    MODEL_FALLBACK = "orbit-fallback-hash-3072"
    EMBEDDING_MODEL = MODEL_GEMINI
    DEFAULT_DIMENSION = 3072
    FALLBACK_DIMENSION = 3072

    def __init__(
        self,
        api_key: Optional[str] = None,
        expected_dimension: int = 3072,
        allow_fallback: Optional[bool] = None,
    ):
        if api_key is not None:
            self.api_key = api_key
        else:
            self.api_key = os.getenv("GEMINI_API_KEY")

        self.expected_dimension = expected_dimension or self.DEFAULT_DIMENSION
        self.FALLBACK_DIMENSION = self.expected_dimension

        # Production fallback must ALWAYS be disabled.
        # Detection must be strictly fail-closed:
        # If Config cannot be imported or production detection raises an exception,
        # fail closed to production mode (is_prod = True) to ensure fallback embeddings
        # can never be generated or enter production vector storage.
        try:
            from config import Config
            is_prod = Config.is_production_mode()
        except Exception as err:
            logger.error(
                f"Production detection failed or Config unavailable ({err}). "
                "Failing closed to production mode to protect vector store integrity."
            )
            is_prod = True

        if is_prod:
            self.allow_fallback = False
        else:
            if allow_fallback is not None:
                self.allow_fallback = allow_fallback
            else:
                self.allow_fallback = (os.getenv("ALLOW_FALLBACK", "true").lower() != "false")

        self._client = None
        if self.api_key and self.api_key.strip() and self.api_key != "mock_key_for_testing":
            try:
                from google import genai
                self._client = genai.Client(api_key=self.api_key)
            except Exception as e:
                logger.warning(f"Could not initialize GenAI client for embeddings: {e}")
                self._client = None

    def embed_text(self, text: str) -> List[float]:
        """Generate embedding vector for a single string."""
        vec, _ = self.embed_text_with_model(text)
        return vec

    def embed_text_with_model(self, text: str) -> Tuple[List[float], str]:
        """Generate embedding vector and return the associated model identifier."""
        if not text:
            model_name = self.EMBEDDING_MODEL if self._client else self.MODEL_FALLBACK
            return [0.0] * self.expected_dimension, model_name

        if self._client:
            try:
                response = self._client.models.embed_content(
                    model=self.EMBEDDING_MODEL,
                    contents=text,
                )
                if hasattr(response, "embeddings") and response.embeddings:
                    values = response.embeddings[0].values
                    if len(values) != self.expected_dimension:
                        msg = (
                            f"GenAI returned vector with unexpected dimension {len(values)}, "
                            f"expected {self.expected_dimension}."
                        )
                        logger.error(msg)
                        if not self.allow_fallback:
                            raise EmbeddingError(msg)
                        return self._fallback_embed(text), self.MODEL_FALLBACK
                    return self._l2_normalize(values), self.EMBEDDING_MODEL
            except EmbeddingError:
                raise
            except Exception as e:
                msg = f"GenAI embedding call failed: {e}"
                logger.warning(msg)
                if not self.allow_fallback:
                    raise EmbeddingError(
                        f"Semantic embedding generation failed in production: {e}. "
                        "Fallback embeddings are prohibited to prevent index contamination."
                    )

        if not self.allow_fallback:
            raise EmbeddingError(
                "Gemini client is not configured; fallback embeddings are prohibited in production "
                "to prevent vector index pollution."
            )

        return self._fallback_embed(text), self.MODEL_FALLBACK

    def embed_batch(self, texts: List[str]) -> List[List[float]]:
        """Generate embeddings for a list of texts."""
        vectors, _ = self.embed_batch_with_model(texts)
        return vectors

    def embed_batch_with_model(self, texts: List[str]) -> Tuple[List[List[float]], str]:
        """Generate embeddings for a list of texts and return the associated model identifier."""
        if not texts:
            return [], self.EMBEDDING_MODEL if self._client else self.MODEL_FALLBACK

        if self._client:
            try:
                response = self._client.models.embed_content(
                    model=self.EMBEDDING_MODEL,
                    contents=texts,
                )
                if hasattr(response, "embeddings") and len(response.embeddings) == len(texts):
                    validated_embeddings = []
                    dimension_mismatch = False
                    for emb in response.embeddings:
                        if len(emb.values) != self.expected_dimension:
                            logger.error(
                                f"GenAI batch item returned unexpected dimension {len(emb.values)}, "
                                f"expected {self.expected_dimension}."
                            )
                            dimension_mismatch = True
                            break
                        validated_embeddings.append(self._l2_normalize(emb.values))
                    if not dimension_mismatch:
                        return validated_embeddings, self.EMBEDDING_MODEL

                    msg = "GenAI batch embeddings had dimension mismatch."
                    logger.warning(msg)
                    if not self.allow_fallback:
                        raise EmbeddingError(msg)
            except EmbeddingError:
                raise
            except Exception as e:
                msg = f"GenAI batch embedding call failed: {e}"
                logger.warning(msg)
                if not self.allow_fallback:
                    raise EmbeddingError(
                        f"Semantic batch embedding generation failed in production: {e}. "
                        "Fallback embeddings are prohibited to prevent index contamination."
                    )

        if not self.allow_fallback:
            raise EmbeddingError(
                "Gemini client is not configured; fallback embeddings are prohibited in production "
                "to prevent vector index pollution."
            )

        return [self._fallback_embed(t) for t in texts], self.MODEL_FALLBACK

    def _fallback_embed(self, text: str) -> List[float]:
        """Deterministic dense token hashing embedding for offline/testing/fallback environments."""
        dim = self.expected_dimension
        vector = [0.0] * dim
        tokens = re.findall(r"\w+", text.lower())
        if not tokens:
            return vector

        # Bag of hashed n-grams & tokens
        for token in tokens:
            h = int(hashlib.sha256(token.encode("utf-8")).hexdigest(), 16)
            idx = h % dim
            weight = 1.0 + (len(token) / 10.0)
            vector[idx] += weight

        # Substring 3-grams for partial match
        clean = re.sub(r"\s+", " ", text.lower().strip())
        for i in range(len(clean) - 2):
            trigram = clean[i:i+3]
            h = int(hashlib.md5(trigram.encode("utf-8")).hexdigest(), 16)
            idx = h % dim
            vector[idx] += 0.3

        return self._l2_normalize(vector)

    @staticmethod
    def _l2_normalize(vec: List[float]) -> List[float]:
        norm = math.sqrt(sum(v * v for v in vec))
        if norm <= 1e-9:
            return vec
        return [v / norm for v in vec]

